mapper.select:
select id,
       content,
       metadata::text as metadata_json
from vector_store
where content_tsv @@ plainto_tsquery('simple', #{keywords})

  and metadata->>'wing' = #{wing}


  and metadata->>'room' = #{room}

order by ts_rank(content_tsv, plainto_tsquery('simple', #{keywords})) desc
limit #{limit}
